"use server";

import { idsNasListas } from "@/features/listas/consultas";
import { obterPreferencias } from "@/features/preferencias/consultas";
import { obterReacoes } from "@/features/reacoes/consultas";
import { limparIds } from "@/features/surpresa/memoria";
import { montarGlobo, type FilmeGlobo } from "@/features/surpresa/montar";
import { createClient } from "@/lib/supabase/server";
import { descobrirFilmes } from "@/lib/tmdb/filmes";

/** Lote novo para o globo, sem os filmes que a pessoa já viu, reagiu ou sorteou. */
export async function novoGlobo(jaVistos: unknown): Promise<FilmeGlobo[]> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return [];

  try {
    const preferencias = await obterPreferencias();
    if (!preferencias) return [];
    const [reacoes, nasListas] = await Promise.all([obterReacoes(), idsNasListas()]);

    return await montarGlobo({
      preferencias,
      excluir: [...nasListas, ...reacoes.map((r) => r.tmdbId), ...limparIds(jaVistos)],
      api: { descobrirFilmes },
    });
  } catch (erro) {
    console.error("[surpresa] falha ao renovar o globo:", erro);
    return [];
  }
}
import { GENEROS } from "@/features/preferencias/generos";
import type { PreferenciasInput } from "@/features/preferencias/schema";
import { motivoPorGeneros } from "@/features/recomendacao/motivo";
import { filtrosDeDuracao, PERFIS } from "@/features/recomendacao/perfil";
import type { ApiFilmes } from "@/lib/tmdb/filmes";
import type { FilmeResumo } from "@/lib/tmdb/tipos";

export type ApiGlobo = Pick<ApiFilmes, "descobrirFilmes">;

export type FilmeGlobo = Pick<FilmeResumo, "id" | "titulo" | "ano" | "nota" | "sinopse"> & {
  posterPath: string;
  motivo: string;
  origem: "gosto" | "bolha";
};

type Entrada = {
  preferencias: PreferenciasInput;
  excluir?: number[];
  api: ApiGlobo;
  /** Gerador em [0, 1); injetável para os testes. */
  aleatorio?: () => number;
};

const POR_ORIGEM = 6;
const GENEROS_BOLHA = 3;
const MINIMO_NO_GLOBO = 3;
const BOLHA = { notaMin: 6.5, votosMin: 500, paginaMax: 5 };

function inteiroEntre(aleatorio: () => number, min: number, max: number) {
  return min + Math.floor(aleatorio() * (max - min + 1));
}

/** Fisher–Yates com o gerador recebido. */
function embaralhar<T>(lista: T[], aleatorio: () => number): T[] {
  const copia = [...lista];
  for (let i = copia.length - 1; i > 0; i--) {
    const j = Math.floor(aleatorio() * (i + 1));
    [copia[i], copia[j]] = [copia[j]!, copia[i]!];
  }
  return copia;
}

type Filtros = NonNullable<Parameters<ApiGlobo["descobrirFilmes"]>[0]>;

async function consultar(api: ApiGlobo, filtros: Filtros): Promise<FilmeResumo[]> {
  try {
    const itens = (await api.descobrirFilmes(filtros)).itens;
    // Gostos de nicho têm poucas páginas no TMDB: se a sorteada não existe, usa a 1ª por nota
    // (os carrosséis ordenam por popularidade, então ainda são filmes diferentes).
    if (itens.length === 0 && (filtros.pagina ?? 1) > 1) {
      return (await api.descobrirFilmes({ ...filtros, pagina: 1, ordem: "nota" })).itens;
    }
    return itens;
  } catch (erro) {
    console.error("[surpresa] consulta falhou:", erro);
    return [];
  }
}

/**
 * Até 6 filmes do gosto da pessoa (de páginas que os carrosséis não usam) e até 6
 * de gêneros que ela não escolheu nem evita, bem avaliados. Lista vazia se sobrarem menos de 3.
 */
export async function montarGlobo({
  preferencias,
  excluir = [],
  api,
  aleatorio = Math.random,
}: Entrada): Promise<FilmeGlobo[]> {
  const perfil = PERFIS[preferencias.frequencia];
  const favoritos = preferencias.generos;
  const evitados = preferencias.generosEvitados;
  const generosBolha = embaralhar(
    GENEROS.map(({ id }) => id).filter((id) => !favoritos.includes(id) && !evitados.includes(id)),
    aleatorio,
  ).slice(0, GENEROS_BOLHA);

  const [doGosto, daBolha] = await Promise.all([
    consultar(api, {
      generos: favoritos,
      ...(evitados.length > 0 && { semGeneros: evitados }),
      ...filtrosDeDuracao(preferencias.duracao),
      votosMin: perfil.votosMin,
      notaMin: perfil.notaMin,
      ordem: "popularidade",
      pagina: inteiroEntre(aleatorio, perfil.paginaMax + 1, perfil.paginaMax + 5),
    }),
    consultar(api, {
      generos: generosBolha,
      semGeneros: [...favoritos, ...evitados],
      notaMin: BOLHA.notaMin,
      votosMin: BOLHA.votosMin,
      ordem: "popularidade",
      pagina: inteiroEntre(aleatorio, 1, BOLHA.paginaMax),
    }),
  ]);

  const vistos = new Set(excluir);
  function escolher(filmes: FilmeResumo[]) {
    const validos = filmes.filter((filme) => {
      if (!filme.posterPath || vistos.has(filme.id)) return false;
      vistos.add(filme.id);
      return true;
    });
    return embaralhar(validos, aleatorio).slice(0, POR_ORIGEM);
  }

  const nomeDoGenero = (filme: FilmeResumo) =>
    GENEROS.find(({ id }) => filme.generos.includes(id) && generosBolha.includes(id))?.nome ??
    "um gênero novo";

  const globo: FilmeGlobo[] = [
    ...escolher(doGosto).map((filme) => ({
      ...resumo(filme),
      motivo: motivoPorGeneros(filme.generos, favoritos),
      origem: "gosto" as const,
    })),
    ...escolher(daBolha).map((filme) => ({
      ...resumo(filme),
      motivo: `Fora da sua bolha: ${nomeDoGenero(filme)} bem avaliado`,
      origem: "bolha" as const,
    })),
  ];

  return globo.length < MINIMO_NO_GLOBO ? [] : embaralhar(globo, aleatorio);
}

function resumo(filme: FilmeResumo) {
  return {
    id: filme.id,
    titulo: filme.titulo,
    ano: filme.ano,
    nota: filme.nota,
    sinopse: filme.sinopse,
    posterPath: filme.posterPath ?? "",
  };
}
/** Filmes já sorteados no "Me surpreenda", guardados no navegador por 24 h. */

export const CHAVE_MEMORIA = "filme-certo:surpresa-vistos";
export const MAX_VISTOS = 200;
const VALIDADE_MS = 24 * 60 * 60 * 1000;

type Entrada = { id: number; em: number };
type Armazenamento = Pick<Storage, "getItem" | "setItem">;

function ler(armazenamento: Armazenamento): Entrada[] {
  try {
    const bruto = JSON.parse(armazenamento.getItem(CHAVE_MEMORIA) ?? "[]");
    return Array.isArray(bruto)
      ? bruto.filter(
          (e): e is Entrada => Number.isInteger(e?.id) && e.id > 0 && Number.isFinite(e?.em),
        )
      : [];
  } catch {
    return [];
  }
}

/** IDs sorteados nas últimas 24 h (lista vazia se o navegador não deixar ler). */
export function lerVistos(armazenamento: Armazenamento | undefined, agora = Date.now()): number[] {
  if (!armazenamento) return [];
  return ler(armazenamento)
    .filter((e) => agora - e.em < VALIDADE_MS)
    .map((e) => e.id);
}

/** Guarda um sorteio, mantendo só as 200 entradas mais recentes e válidas. */
export function registrarVisto(
  armazenamento: Armazenamento | undefined,
  id: number,
  agora = Date.now(),
): void {
  if (!armazenamento) return;
  try {
    const entradas = ler(armazenamento).filter((e) => e.id !== id && agora - e.em < VALIDADE_MS);
    entradas.push({ id, em: agora });
    armazenamento.setItem(CHAVE_MEMORIA, JSON.stringify(entradas.slice(-MAX_VISTOS)));
  } catch {
    // Sem localStorage (modo privado, bloqueio): vale só a regra da sessão.
  }
}

/** Acesso seguro ao localStorage: `undefined` quando o navegador bloqueia. */
export function armazenamentoLocal(): Storage | undefined {
  try {
    return window.localStorage;
  } catch {
    return undefined;
  }
}

/** Limpa IDs vindos do navegador: só inteiros positivos, sem repetidos, no máximo 200. */
export function limparIds(valor: unknown): number[] {
  if (!Array.isArray(valor)) return [];
  const ids = valor.filter((id): id is number => Number.isInteger(id) && id > 0);
  return [...new Set(ids)].slice(0, MAX_VISTOS);
}
import type { Duracao, Frequencia } from "@/features/preferencias/opcoes";
import type { FiltrosDescoberta } from "@/lib/tmdb/tipos";

export function filtrosDeDuracao(
  duracao: Duracao,
): Pick<FiltrosDescoberta, "duracaoMin" | "duracaoMax"> {
  switch (duracao) {
    case "curta":
      return { duracaoMax: 90 };
    case "media":
      return { duracaoMin: 90, duracaoMax: 120 };
    case "longa":
      return { duracaoMin: 120 };
    case "indiferente":
      return {};
  }
}

/**
 * Quanto mais a pessoa assiste, menos óbvios os filmes: menos votos e nota mínimos
 * e páginas mais fundas do TMDB. Quem assiste pouco recebe os consagrados.
 */
export const PERFIS: Record<Frequencia, { votosMin: number; notaMin: number; paginaMax: number }> =
  {
    raramente: { votosMin: 2000, notaMin: 7, paginaMax: 2 },
    mensal: { votosMin: 1000, notaMin: 6.5, paginaMax: 3 },
    semanal: { votosMin: 300, notaMin: 6.5, paginaMax: 5 },
    diaria: { votosMin: 100, notaMin: 6, paginaMax: 10 },
  };
import { z } from "zod";

/** Limite de trocas do wizard (pedido do cliente, 3.2). */
export const MAX_TROCAS = 5;

export const MOTIVOS_TROCA = ["ja-vi", "nao-e-o-clima", "muito-longo", "outro"] as const;
export const RESPOSTAS_COMO_FOI = ["amei", "gostei", "nao-gostei", "nao-vi"] as const;
export const ORIGENS_TRAILER = ["filme", "noite"] as const;
export const ETAPAS_WIZARD = ["perguntas", "resultado"] as const;

export type OrigemTrailer = (typeof ORIGENS_TRAILER)[number];

const semDados = z.strictObject({}).default({});

/**
 * Lista fechada de eventos e os dados de cada um (SPEC/2026-11-18-metricas.md).
 * Objetos estritos: qualquer chave a mais, como o clima do wizard, é recusada.
 */
export const eventoSchema = z.discriminatedUnion("nome", [
  z.object({ nome: z.literal("wizard_iniciado"), dados: semDados }),
  z.object({ nome: z.literal("wizard_concluido"), dados: semDados }),
  z.object({
    nome: z.literal("wizard_troca"),
    dados: z.strictObject({ motivo: z.enum(MOTIVOS_TROCA) }),
  }),
  z.object({
    nome: z.literal("wizard_escolheu"),
    dados: z.strictObject({ trocas: z.number().int().min(0).max(MAX_TROCAS) }),
  }),
  z.object({
    nome: z.literal("wizard_abandonado"),
    dados: z.strictObject({ etapa: z.enum(ETAPAS_WIZARD) }),
  }),
  z.object({ nome: z.literal("como_foi_exibido"), dados: semDados }),
  z.object({
    nome: z.literal("como_foi_respondido"),
    dados: z.strictObject({ resposta: z.enum(RESPOSTAS_COMO_FOI) }),
  }),
  z.object({
    nome: z.literal("trailer_aberto"),
    dados: z.strictObject({ origem: z.enum(ORIGENS_TRAILER) }),
  }),
]);

/** Evento como quem registra escreve (`dados` pode faltar nos eventos sem dados). */
export type Evento = z.input<typeof eventoSchema>;
export type NomeEvento = Evento["nome"];

/** Respostas do wizard contadas sem vínculo com a pessoa. */
export const CLIMAS = {
  humor: ["cansado", "animado", "pra-baixo", "nostalgico", "ansioso", "de-boa"],
  experiencia: ["rir", "emocionar", "susto", "tenso", "pensar", "distrair"],
  companhia: ["sozinho", "a-dois", "familia", "amigos"],
} as const;

export type Pergunta = keyof typeof CLIMAS;

export const climaSchema = z.object({
  humor: z.enum(CLIMAS.humor),
  experiencia: z.enum(CLIMAS.experiencia),
  companhia: z.enum(CLIMAS.companhia),
});

export type Clima = z.infer<typeof climaSchema>;
import "server-only";

import { climaSchema, eventoSchema, type Clima, type Evento } from "@/features/metricas/eventos";
import type { ClienteSupabase } from "@/lib/supabase/token";

type RespostaBanco = { error: { code: string; message: string } | null };

/** Executa a escrita e transforma qualquer falha em `false` com log. */
async function semLancar(acao: string, escrever: () => PromiseLike<RespostaBanco>) {
  try {
    const { error } = await escrever();
    if (!error) return true;
    console.error(`[metricas] falha ao ${acao}:`, error.code, error.message);
  } catch (erro) {
    console.error(`[metricas] falha ao ${acao}:`, erro);
  }
  return false;
}

/**
 * Registra um evento de uso do usuário logado (o `usuario_id` vem do banco, por `auth.uid()`).
 * Nunca lança: métrica não pode quebrar a tela. Devolve se gravou.
 */
export async function registrarEvento(supabase: ClienteSupabase, evento: Evento): Promise<boolean> {
  const valido = eventoSchema.safeParse(evento);
  if (!valido.success) {
    console.error("[metricas] evento inválido:", evento.nome);
    return false;
  }
  const { nome, dados } = valido.data;
  return semLancar("registrar", () => supabase.from("eventos").insert({ nome, dados }));
}

/** Conta as respostas do wizard sem vínculo com a pessoa. Nunca lança. */
export async function registrarClima(supabase: ClienteSupabase, clima: Clima): Promise<boolean> {
  const valido = climaSchema.safeParse(clima);
  if (!valido.success) {
    console.error("[metricas] clima inválido");
    return false;
  }
  const { humor, experiencia, companhia } = valido.data;
  return semLancar("contar clima", () =>
    supabase.rpc("registrar_clima", {
      p_humor: humor,
      p_experiencia: experiencia,
      p_companhia: companhia,
    }),
  );
}

