import { obterFilme } from "@/lib/tmdb/filmes";

/** Só inteiros positivos de até 10 dígitos são IDs válidos do TMDB. */
function lerId(valor: string): number | null {
  if (!/^\d{1,10}$/.test(valor)) return null;
  const id = Number(valor);
  return id > 0 ? id : null;
}

/** Uma busca por renderização, compartilhada entre a página e o título da aba. */
const buscarFilme = cache(async (valor: string) => {
  const id = lerId(valor);
  return id ? obterFilme(id) : null;
});

export async function generateMetadata({ params }: PageProps<"/filme/[id]">): Promise<Metadata> {
  const filme = await buscarFilme((await params).id);
  if (!filme) return { title: "Filme não encontrado" };
  return { title: filme.ano ? `${filme.titulo} (${filme.ano})` : filme.titulo };
}

function Secao({ titulo, children }: { titulo: string; children: React.ReactNode }) {
  return (
    <section className="flex flex-col gap-4">
      <h2 className="text-2xl tracking-tight">{titulo}</h2>
      {children}
    </section>
  );
}

export default async function FilmePage({ params }: PageProps<"/filme/[id]">) {
  const filme = await buscarFilme((await params).id);
  if (!filme) notFound();
  const [reacao, statusLista] = await Promise.all([
    obterReacao(filme.id),
    obterStatusLista(filme.id),
  ]);

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-1 flex-col gap-10 px-4 py-8">
      <Link
        href="/dashboard"
        className="text-muted-foreground hover:text-foreground inline-flex w-fit items-center gap-1 text-sm"
      >
        <ArrowLeft className="size-4" aria-hidden="true" /> Voltar
      </Link>

      <CabecalhoFilme
        filme={filme}
        acoes={
          <>
            <BotoesReacao key={`r-${reacao}`} tmdbId={filme.id} atual={reacao} />
            <BotoesLista key={`l-${statusLista}`} tmdbId={filme.id} atual={statusLista} />
          </>
        }
      />

      <Secao titulo="Sinopse">
        <p className="max-w-3xl leading-relaxed">
          {filme.sinopse || "Sinopse não disponível em português."}
        </p>
        {filme.direcao.length > 0 && (
          <p className="text-muted-foreground text-sm">Direção: {filme.direcao.join(", ")}</p>
        )}
      </Secao>

      {filme.trailerYoutube && (
        <Secao titulo="Trailer">
          <Trailer chave={filme.trailerYoutube} titulo={filme.titulo} origem="filme" />
        </Secao>
      )}

      <Secao titulo="Onde assistir no Brasil">
        <OndeAssistir dados={filme.ondeAssistir} />
      </Secao>

      {filme.elenco.length > 0 && (
        <Secao titulo="Elenco">
          <Elenco pessoas={filme.elenco} />
        </Secao>
      )}

      {filme.parecidos.length > 0 && (
        <section aria-labelledby="titulo-parecidos" className="flex flex-col gap-4">
          <h2 id="titulo-parecidos" className="text-2xl tracking-tight">
            Filmes parecidos
          </h2>
          <Carrossel rotulo="Filmes parecidos">
            {filme.parecidos.map((parecido) => (
              <li key={parecido.id} className="shrink-0 snap-start">
                <CartaoFilme filme={parecido} />
              </li>
            ))}
          </Carrossel>
        </section>
      )}
    </div>
  );
}
"use client";

import { Play } from "lucide-react";
import Image from "next/image";
import { useState } from "react";

import { enviarEvento } from "@/features/metricas/enviar";
import type { OrigemTrailer } from "@/features/metricas/eventos";

/**
 * Miniatura do YouTube; o player (sem cookies) só é carregado depois do clique.
 * Com `origem`, o clique registra o evento `trailer_aberto` (SPEC/2026-11-18-metricas.md).
 */
export function Trailer({
  chave,
  titulo,
  origem,
}: {
  chave: string;
  titulo: string;
  origem?: OrigemTrailer;
}) {
  const [tocando, setTocando] = useState(false);

  function abrir() {
    setTocando(true);
    if (origem) enviarEvento({ nome: "trailer_aberto", dados: { origem } });
  }

  return (
    <div className="bg-muted relative aspect-video w-full max-w-3xl overflow-hidden rounded-xl">
      {tocando ? (
        <iframe
          src={`https://www.youtube-nocookie.com/embed/${chave}?autoplay=1`}
          title={`Trailer de ${titulo}`}
          allow="autoplay; encrypted-media; picture-in-picture"
          allowFullScreen
          className="absolute inset-0 size-full"
        />
      ) : (
        <button
          type="button"
          onClick={abrir}
          className="group focus-visible:ring-ring/50 absolute inset-0 outline-none focus-visible:ring-3"
        >
          <Image
            src={`https://i.ytimg.com/vi/${chave}/hqdefault.jpg`}
            alt=""
            fill
            sizes="(min-width: 768px) 768px, 100vw"
            className="object-cover opacity-80 transition-opacity group-hover:opacity-100"
          />
          <span className="bg-primary text-primary-foreground absolute top-1/2 left-1/2 flex -translate-x-1/2 -translate-y-1/2 items-center gap-2 rounded-full px-5 py-3 font-medium shadow-lg">
            <Play className="size-5 fill-current" aria-hidden="true" />
            Assistir trailer
          </span>
        </button>
      )}
    </div>
  );
}
/** "2h 19min", "2h", "45min"; `null` para duração ausente. */
export function formatarDuracao(minutos: number | null): string | null {
  if (!minutos) return null;
  const horas = Math.floor(minutos / 60);
  const resto = minutos % 60;
  if (!horas) return `${resto}min`;
  return resto ? `${horas}h ${resto}min` : `${horas}h`;
}

const numeroPtBr = new Intl.NumberFormat("pt-BR");

export function formatarVotos(votos: number): string {
  return numeroPtBr.format(votos);
}
import { ExternalLink } from "lucide-react";
import Image from "next/image";

import { urlImagem } from "@/lib/tmdb/imagens";
import type { OndeAssistir as Dados, Provedor } from "@/lib/tmdb/tipos";

const GRUPOS = [
  { chave: "assinatura", titulo: "Assinatura" },
  { chave: "aluguel", titulo: "Aluguel" },
  { chave: "compra", titulo: "Compra" },
] as const;

function Provedores({ titulo, provedores }: { titulo: string; provedores: Provedor[] }) {
  return (
    <div className="flex flex-col gap-2">
      <h3 className="text-muted-foreground text-sm font-medium">{titulo}</h3>
      <ul className="flex flex-wrap gap-3">
        {provedores.map((provedor) => {
          const logo = urlImagem(provedor.logoPath, "w92");
          return (
            <li key={provedor.id} className="flex items-center gap-2">
              {logo ? (
                <Image
                  src={logo}
                  alt={provedor.nome}
                  width={36}
                  height={36}
                  className="rounded-md"
                />
              ) : (
                <span aria-hidden="true" className="bg-muted size-9 rounded-md" />
              )}
              <span className="text-sm">{provedor.nome}</span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

export function OndeAssistir({ dados }: { dados: Dados | null }) {
  const grupos = GRUPOS.filter(({ chave }) => dados && dados[chave].length > 0);

  if (!dados || grupos.length === 0) {
    return (
      <p className="text-muted-foreground">Não encontramos onde assistir este filme no Brasil.</p>
    );
  }

  return (
    <div className="flex flex-col gap-4">
      {grupos.map(({ chave, titulo }) => (
        <Provedores key={chave} titulo={titulo} provedores={dados[chave]} />
      ))}
      <a
        href={dados.link}
        target="_blank"
        rel="noopener noreferrer"
        className="text-primary inline-flex w-fit items-center gap-1 text-sm underline-offset-4 hover:underline"
      >
        Ver todas as opções <ExternalLink className="size-3.5" aria-hidden="true" />
      </a>
      <p className="text-muted-foreground text-xs">
        Dados de onde assistir fornecidos por JustWatch.
      </p>
    </div>
  );
}
import { GENEROS } from "@/features/preferencias/generos";
import { VERBO_REACAO } from "@/features/reacoes/opcoes";
import type { ReacaoMotor } from "@/features/recomendacao/tipos";

const MAX_GENEROS_NO_MOTIVO = 3;

function listar(nomes: string[]): string {
  if (nomes.length <= 1) return nomes.join("");
  return `${nomes.slice(0, -1).join(", ")} e ${nomes.at(-1)}`;
}

/** "Porque você curte Drama e Thriller", com no máximo 3 gêneros, na ordem de GENEROS. */
export function motivoPorGeneros(generosDoFilme: number[], favoritos: number[]): string {
  const emComum = GENEROS.filter(
    ({ id }) => generosDoFilme.includes(id) && favoritos.includes(id),
  ).map(({ nome }) => nome);
  if (emComum.length === 0) return "Popular entre quem tem gostos parecidos";
  return `Porque você curte ${listar(emComum.slice(0, MAX_GENEROS_NO_MOTIVO))}`;
}

/** "Parecido com X, que você amou". */
export function motivoParecido(origem: ReacaoMotor): string {
  const verbo = origem.reacao === "nao-gostei" ? null : VERBO_REACAO[origem.reacao];
  return verbo ? `Parecido com ${origem.titulo}, ${verbo.motivo}` : `Parecido com ${origem.titulo}`;
}

/** "Porque você amou X" / "Porque você gostou de X". */
export function tituloParecidos(origem: ReacaoMotor): string {
  const verbo = origem.reacao === "nao-gostei" ? null : VERBO_REACAO[origem.reacao];
  return verbo ? `${verbo.titulo} ${origem.titulo}` : `Parecidos com ${origem.titulo}`;
}
import { NextResponse, type NextRequest } from "next/server";

import { DESTINO_PADRAO } from "@/features/auth/redirecionamento";
import { updateSession } from "@/lib/supabase/middleware";

/** Rotas que exigem sessão: a área logada (grupo `(app)`) e o onboarding. */
const ROTAS_PROTEGIDAS = [
  "/dashboard",
  "/onboarding",
  "/filme",
  "/listas",
  "/busca",
  "/perfil",
  "/oauth",
  "/metricas",
];
/** Rotas que só fazem sentido sem sessão. */
const ROTAS_DE_VISITANTE = ["/", "/login", "/cadastro"];

function corresponde(caminho: string, rotas: string[]) {
  return rotas.some((rota) => caminho === rota || caminho.startsWith(`${rota}/`));
}

/** Redireciona mantendo os cookies de sessão que o Supabase acabou de renovar. */
function redirecionar(destino: URL, response: NextResponse) {
  const redirect = NextResponse.redirect(destino);
  for (const cookie of response.cookies.getAll()) redirect.cookies.set(cookie);
  return redirect;
}

/**
 * Checagem otimista: renova a sessão e redireciona antes de renderizar.
 * A checagem definitiva fica no layout de `(app)` e na RLS do banco.
 */
export async function proxy(request: NextRequest) {
  const { response, user } = await updateSession(request);
  const { pathname, search } = request.nextUrl;

  if (!user && corresponde(pathname, ROTAS_PROTEGIDAS)) {
    const login = new URL("/login", request.url);
    login.searchParams.set("next", `${pathname}${search}`);
    return redirecionar(login, response);
  }

  if (user && ROTAS_DE_VISITANTE.includes(pathname)) {
    return redirecionar(new URL(DESTINO_PADRAO, request.url), response);
  }

  return response;
}

export const config = {
  matcher: [
    "/((?!api|_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
  ],
};

