      "videos,credits,watch/providers,recommendations",
    );
    expect(url.searchParams.get("language")).toBe("pt-BR");
    expect(revalidate).toBe(24 * 3600);

    expect(filme).toMatchObject({
      id: 550,
      titulo: "Clube da Luta",
      ano: 1999,
      generos: [
